import SwiftUI

// Plasmie's geometry, renderer-agnostic. The anchors come from PlasmieShapes (generated by
// app/brand/gen_shapes.py): 12 points on a 100x100 canvas, y down, clockwise from 12
// o'clock. A closed Catmull-Rom spline through them is the body; blending two states'
// anchors is the morph. Face marks are plain paths so the live view (ink on body) and
// the menu-bar glyph (knocked out of a template silhouette) share one drawing.

// MARK: - the 11 states

enum PlasmieState: String, CaseIterable {
    case idle, ingest, summarize, promote, ask, held, error, busy, quiet, off, success

    var anchors: [CGPoint] { PlasmieShapes.anchors[rawValue] ?? PlasmieShapes.anchors["idle"] ?? [] }

    var label: String {
        switch self {
        case .idle:      return "Plasmie is resting. Everything is flowing"
        case .ingest:    return "Plasmie is catching new activity"
        case .summarize: return "Plasmie is summarising your day"
        case .promote:   return "Plasmie is filing new notes"
        case .ask:       return "Plasmie is looking into your question"
        case .held:      return "Plasmie is holding items for your review"
        case .error:     return "Plasmie hit a problem and needs attention"
        case .busy:      return "Plasmie is waiting while the Mac is busy"
        case .quiet:     return "Plasmie is quiet. Nothing new for a while"
        case .off:       return "Plasmie is switched off"
        case .success:   return "Plasmie finished successfully"
        }
    }

    /// States whose menu-bar glyph keeps moving while they last.
    var animatesMenuBar: Bool {
        switch self {
        case .ingest, .summarize, .promote, .ask, .busy: return true
        default: return false
        }
    }
}

// MARK: - animatable vector

/// An animatable bag of CGFloats. Missing trailing elements read as 0, so two vectors of
/// different length still blend. SwiftUI interpolates this natively between two values.
struct PlasmieVector: VectorArithmetic {
    var v: [CGFloat]
    static let zero = PlasmieVector(v: [])

    init(v: [CGFloat]) { self.v = v }
    init(points: [CGPoint]) { v = points.flatMap { [$0.x, $0.y] } }

    var points: [CGPoint] {
        stride(from: 0, to: v.count - 1, by: 2).map { CGPoint(x: v[$0], y: v[$0 + 1]) }
    }

    private static func zipped(_ a: PlasmieVector, _ b: PlasmieVector, _ f: (CGFloat, CGFloat) -> CGFloat) -> PlasmieVector {
        let n = max(a.v.count, b.v.count)
        return PlasmieVector(v: (0..<n).map { f($0 < a.v.count ? a.v[$0] : 0, $0 < b.v.count ? b.v[$0] : 0) })
    }
    static func + (a: PlasmieVector, b: PlasmieVector) -> PlasmieVector { zipped(a, b, +) }
    static func - (a: PlasmieVector, b: PlasmieVector) -> PlasmieVector { zipped(a, b, -) }
    mutating func scale(by rhs: Double) { v = v.map { $0 * CGFloat(rhs) } }
    var magnitudeSquared: Double { v.reduce(0) { $0 + Double($1 * $1) } }
}

// MARK: - spline + shape

enum PlasmieSpline {
    /// Closed Catmull-Rom through `p`: segment p1->p2 uses c1 = p1 + (p2-p0)/6, c2 = p2 - (p3-p1)/6.
    static func path(_ p: [CGPoint]) -> Path {
        let n = p.count
        guard n >= 3 else { return Path() }
        var path = Path()
        path.move(to: p[0])
        for i in 0..<n {
            let p0 = p[(i + n - 1) % n], p1 = p[i], p2 = p[(i + 1) % n], p3 = p[(i + 2) % n]
            path.addCurve(to: p2,
                          control1: CGPoint(x: p1.x + (p2.x - p0.x) / 6, y: p1.y + (p2.y - p0.y) / 6),
                          control2: CGPoint(x: p2.x - (p3.x - p1.x) / 6, y: p2.y - (p3.y - p1.y) / 6))
        }
        path.closeSubpath()
        return path
    }

    static func lerp(_ a: [CGPoint], _ b: [CGPoint], _ t: CGFloat) -> [CGPoint] {
        zip(a, b).map { CGPoint(x: $0.x + ($1.x - $0.x) * t, y: $0.y + ($1.y - $0.y) * t) }
    }

    static func bounds(_ p: [CGPoint]) -> CGRect {
        guard let f = p.first else { return .zero }
        var r = CGRect(origin: f, size: .zero)
        for q in p { r = r.union(CGRect(origin: q, size: .zero)) }
        return r
    }
}

/// Plasmie's body. `animatableData` is the 24 anchor coordinates, so
/// `withAnimation { shape = other }` morphs between states with no extra code.
struct PlasmieShape: Shape {
    var vec: PlasmieVector
    init(state: PlasmieState) { vec = PlasmieVector(points: state.anchors) }
    init(vec: PlasmieVector) { self.vec = vec }
    var animatableData: PlasmieVector {
        get { vec }
        set { vec = newValue }
    }
    func path(in rect: CGRect) -> Path {
        let sx = rect.width / 100, sy = rect.height / 100
        // Count-agnostic: N anchors = vec.v.count / 2 (any odd trailing element is ignored).
        let pts = vec.points.map { CGPoint(x: rect.minX + $0.x * sx, y: rect.minY + $0.y * sy) }
        return PlasmieSpline.path(pts)
    }
}

// MARK: - face table (mirrors FACES in app/brand/gen_shapes.py)

enum PlasmieEyes { case dot, happy, wink, up, worried, flat, closed }
enum PlasmieMouth { case smile, o, flat, small, wobble, grin, none }
enum PlasmieProp { case dots, card, spark, bang, sweat, sand, zzz, sparkles }

/// Where the face sits, relative to the body's bounding box so it stays on the body in
/// every shape. Blended across a morph.
struct PlasmieLayout {
    var cx: CGFloat = 0.5      // eye-line centre, fraction of bbox width
    var cy: CGFloat = 0.46     // eye line, fraction of bbox height
    var gap: CGFloat = 0.17    // half eye distance, fraction of bbox width
    var mouthDy: CGFloat = 8   // mouth below the eye line, canvas units
    var scale: CGFloat = 1

    static func mix(_ a: PlasmieLayout, _ b: PlasmieLayout, _ t: CGFloat) -> PlasmieLayout {
        func l(_ x: CGFloat, _ y: CGFloat) -> CGFloat { x + (y - x) * t }
        return PlasmieLayout(cx: l(a.cx, b.cx), cy: l(a.cy, b.cy), gap: l(a.gap, b.gap),
                           mouthDy: l(a.mouthDy, b.mouthDy), scale: l(a.scale, b.scale))
    }
}

struct PlasmieFace {
    let eyes: PlasmieEyes
    let mouth: PlasmieMouth
    let prop: PlasmieProp?
    var blush = false
    var layout = PlasmieLayout()
}

extension PlasmieState {
    var face: PlasmieFace {
        switch self {
        case .idle:      return PlasmieFace(eyes: .dot, mouth: .smile, prop: nil, blush: true)
        case .ingest:    return PlasmieFace(eyes: .dot, mouth: .o, prop: .dots, layout: PlasmieLayout(cy: 0.55, gap: 0.165, mouthDy: 9))
        case .summarize: return PlasmieFace(eyes: .happy, mouth: .flat, prop: nil, layout: PlasmieLayout(cy: 0.5, gap: 0.17, mouthDy: 8))
        case .promote:   return PlasmieFace(eyes: .wink, mouth: .smile, prop: .card)
        case .ask:       return PlasmieFace(eyes: .up, mouth: .small, prop: .spark, layout: PlasmieLayout(cy: 0.37, gap: 0.17, mouthDy: 9))
        case .held:      return PlasmieFace(eyes: .dot, mouth: .o, prop: .bang, blush: true, layout: PlasmieLayout(cx: 0.48, cy: 0.56, gap: 0.15, mouthDy: 8.5))
        case .error:     return PlasmieFace(eyes: .worried, mouth: .wobble, prop: .sweat, layout: PlasmieLayout(cy: 0.42, gap: 0.17, mouthDy: 8))
        case .busy:      return PlasmieFace(eyes: .flat, mouth: .flat, prop: .sand, layout: PlasmieLayout(cy: 0.17, gap: 0.17, mouthDy: 5.5, scale: 0.85))
        case .quiet:     return PlasmieFace(eyes: .closed, mouth: .none, prop: .zzz, layout: PlasmieLayout(cy: 0.42, gap: 0.14))
        case .off:       return PlasmieFace(eyes: .closed, mouth: .none, prop: nil, layout: PlasmieLayout(cy: 0.5, gap: 0.15, scale: 0.9))
        case .success:   return PlasmieFace(eyes: .happy, mouth: .grin, prop: .sparkles, blush: true, layout: PlasmieLayout(cy: 0.5, gap: 0.15, mouthDy: 8.5))
        }
    }
}

// MARK: - face marks

struct PlasmieMark {
    enum Tone { case ink, blush }
    var path: Path
    var stroke: CGFloat?     // nil = filled
    var tone: Tone
}

enum PlasmieFaceArt {
    /// Eyes, mouth and blush for `face`, positioned inside `box` (canvas units).
    /// `eye`/`line` scale dot size and stroke weight (the 18pt glyph needs bolder marks).
    static func marks(_ face: PlasmieFace, layout: PlasmieLayout, box: CGRect,
                      eye: CGFloat = 1, line: CGFloat = 1) -> [PlasmieMark] {
        let s = layout.scale
        let ex = box.minX + layout.cx * box.width
        let ey = box.minY + layout.cy * box.height
        let gap = layout.gap * box.width
        let l = CGPoint(x: ex - gap, y: ey), r = CGPoint(x: ex + gap, y: ey)
        let my = ey + layout.mouthDy * s
        let w = 2.3 * s * line
        var out: [PlasmieMark] = []

        func dot(_ c: CGPoint) -> PlasmieMark {
            let rad = 3.0 * s * eye
            return PlasmieMark(path: Path(ellipseIn: CGRect(x: c.x - rad, y: c.y - rad, width: 2 * rad, height: 2 * rad)),
                             stroke: nil, tone: .ink)
        }
        func arc(_ a: CGPoint, _ b: CGPoint, _ ctl: CGPoint, _ width: CGFloat) -> PlasmieMark {
            var p = Path(); p.move(to: a); p.addQuadCurve(to: b, control: ctl)
            return PlasmieMark(path: p, stroke: width, tone: .ink)
        }
        func happy(_ c: CGPoint) -> PlasmieMark {
            arc(CGPoint(x: c.x - 3.6 * s, y: c.y + 1.6 * s), CGPoint(x: c.x + 3.6 * s, y: c.y + 1.6 * s),
                CGPoint(x: c.x, y: c.y - 4.6 * s), w)
        }
        func closed(_ c: CGPoint) -> PlasmieMark {
            arc(CGPoint(x: c.x - 3.6 * s, y: c.y - 1 * s), CGPoint(x: c.x + 3.6 * s, y: c.y - 1 * s),
                CGPoint(x: c.x, y: c.y + 4.2 * s), w)
        }
        func lineMark(_ a: CGPoint, _ b: CGPoint, _ width: CGFloat) -> PlasmieMark {
            var p = Path(); p.move(to: a); p.addLine(to: b)
            return PlasmieMark(path: p, stroke: width, tone: .ink)
        }

        switch face.eyes {
        case .dot:     out += [dot(l), dot(r)]
        case .happy:   out += [happy(l), happy(r)]
        case .wink:    out += [dot(l), happy(r)]
        case .up:      out += [dot(CGPoint(x: l.x, y: l.y - 2.6 * s)), dot(CGPoint(x: r.x, y: r.y - 2.6 * s))]
        case .worried:
            out += [dot(l), dot(r)]
            // brows are fine detail: skipped on the 18pt glyph (line > 1), where they read as noise
            if line <= 1.01 { out += [lineMark(CGPoint(x: l.x - 3.6 * s, y: l.y - 5.2 * s), CGPoint(x: l.x + 3.2 * s, y: l.y - 8.6 * s), 1.8 * s * line),
                    lineMark(CGPoint(x: r.x + 3.6 * s, y: r.y - 5.2 * s), CGPoint(x: r.x - 3.2 * s, y: r.y - 8.6 * s), 1.8 * s * line)] }
        case .flat:
            out += [lineMark(CGPoint(x: l.x - 3.2 * s, y: l.y), CGPoint(x: l.x + 3.2 * s, y: l.y), w * 1.05),
                    lineMark(CGPoint(x: r.x - 3.2 * s, y: r.y), CGPoint(x: r.x + 3.2 * s, y: r.y), w * 1.05)]
        case .closed:  out += [closed(l), closed(r)]
        }

        let mx = ex
        switch face.mouth {
        case .smile: out.append(arc(CGPoint(x: mx - 4.6 * s, y: my), CGPoint(x: mx + 4.6 * s, y: my), CGPoint(x: mx, y: my + 5.4 * s), w))
        case .small: out.append(arc(CGPoint(x: mx - 2.8 * s, y: my), CGPoint(x: mx + 2.8 * s, y: my), CGPoint(x: mx, y: my + 3 * s), w))
        case .flat:  out.append(lineMark(CGPoint(x: mx - 3.6 * s, y: my), CGPoint(x: mx + 3.6 * s, y: my), w))
        case .o:
            let rx = 2.9 * s * eye, ry = 3.5 * s * eye
            out.append(PlasmieMark(path: Path(ellipseIn: CGRect(x: mx - rx, y: my - ry, width: 2 * rx, height: 2 * ry)), stroke: nil, tone: .ink))
        case .wobble:
            var p = Path()
            p.move(to: CGPoint(x: mx - 5.5 * s, y: my))
            p.addCurve(to: CGPoint(x: mx, y: my),
                       control1: CGPoint(x: mx - 4 * s, y: my - 3 * s), control2: CGPoint(x: mx - 1.6 * s, y: my + 3 * s))
            p.addCurve(to: CGPoint(x: mx + 5.5 * s, y: my),
                       control1: CGPoint(x: mx + 1.6 * s, y: my - 3 * s), control2: CGPoint(x: mx + 4 * s, y: my + 3 * s))
            out.append(PlasmieMark(path: p, stroke: w, tone: .ink))
        case .grin:
            var p = Path()
            p.move(to: CGPoint(x: mx - 5.6 * s, y: my - 1.4 * s))
            p.addQuadCurve(to: CGPoint(x: mx + 5.6 * s, y: my - 1.4 * s), control: CGPoint(x: mx, y: my + 12 * s))
            p.closeSubpath()
            out.append(PlasmieMark(path: p, stroke: nil, tone: .ink))
        case .none: break
        }

        if face.blush {
            for sign: CGFloat in [-1, 1] {
                let c = CGPoint(x: ex + sign * (gap + 5.4 * s), y: ey + 5.6 * s)
                out.append(PlasmieMark(path: Path(ellipseIn: CGRect(x: c.x - 4.2 * s, y: c.y - 2.6 * s, width: 8.4 * s, height: 5.2 * s)),
                                     stroke: nil, tone: .blush))
            }
        }
        return out
    }
}
